use super::appendix_a::{FRAME_FULL_EM, FRAME_HALF_EM};

/// One compatibility decomposition Appendix A's preamble requires folding.
///
/// JLReq: §A preamble
#[derive(Debug)]
pub(crate) struct Fold {
    /// The compatibility code point real Japanese text carries.
    pub(crate) source: u32,
    /// The code point Appendix A keys.
    pub(crate) target: u32,
    /// The frame the source code point itself asserts.
    pub(crate) frame: u8,
}

impl Fold {
    /// One row of the table below.
    const fn new(source: u32, target: u32, frame: u8) -> Self {
        Self {
            source,
            target,
            frame,
        }
    }
}

